import Link from "next/link";
import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, Wave 10 (2026-09-24).
 *
 * PREVIEW_GAMES.armareforger was authored directly from the real seeded
 * GamePlan rows (prisma/seed-wave10-games.ts — 6GB/16-player $14.99,
 * 10GB/32-player $24.99 popular, 16GB/64-player $39.99), so no price
 * override is needed here.
 */

export const metadata: Metadata = {
  title: "Arma Reforger Server Hosting — Instant Setup",
  description:
    "Managed Arma Reforger server hosting from $14.99/mo. Conflict, Game Master and Combat Ops scenarios, full admin control, and instant setup on a low-latency Singapore network.",
  alternates: { canonical: "/arma-reforger-server-hosting" },
  openGraph: {
    type: "article",
    title: "Arma Reforger Server Hosting — Instant Setup",
    description:
      "Managed Arma Reforger hosting: choice of scenario, full admin control, and instant setup on a low-latency Singapore network. From $14.99/mo.",
    url: `${APP_URL}/arma-reforger-server-hosting`,
  },
};

const GAME = PREVIEW_GAMES.armareforger;

const FAQ = [
  {
    q: "What is Arma Reforger?",
    a: "Arma Reforger is Bohemia Interactive's tactical military sim — large-scale Conflict campaigns, admin-scripted Game Master sandboxes and smaller Combat Ops matches, all on Bohemia's own dedicated-server tool.",
  },
  {
    q: "Which plan do I need?",
    a: "The 6 GB / 16-player Skirmish plan at $14.99 suits a small squad. The 10 GB / 32-player Offensive plan at $24.99 is our popular pick for real combined-arms battles. Choose the 16 GB / 64-player Total War plan at $39.99 for the largest official Conflict campaigns the engine supports.",
  },
  {
    q: "Can I pick which scenario runs?",
    a: "Yes — choose Conflict on Everon or Arland, a Game Master sandbox, or Combat Ops right from the panel. Switching scenarios doesn't need a reinstall.",
  },
  {
    q: "Is BattlEye anti-cheat included?",
    a: "Yes, BattlEye ships on by default, and your server gets its own generated admin login at first boot — no shared or default admin password.",
  },
  {
    q: "How quickly is my server ready?",
    a: "Setup is instant — your Arma Reforger server is provisioned and online within minutes of ordering, so your operation can kick off the same day.",
  },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "Squad hosting", href: "/squad-server-hosting" },
  { label: "Insurgency: Sandstorm hosting", href: "/sandstorm-server-hosting" },
  { label: "Pricing", href: "/pricing" },
];

export default function ArmaReforgerServerHostingPage() {
  return (
    <>
      <FaqJsonLd items={FAQ} />
      <ProductOffersJsonLd
        name="Nxeon Arma Reforger Server Hosting"
        description={GAME.deck}
        url={`${APP_URL}/game-servers`}
        offers={GAME.plans.map((p) => ({
          name: `${GAME.name} ${p.tier} (${p.ram})`,
          price: parseFloat(p.price.replace(/[^0-9.]/g, "")),
        }))}
      />

      <GameLandingCombined game={GAME} reviewBadges={<ReviewBadges />} />

      {/* FAQ */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {FAQ.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
      </Section>

      {/* Related */}
      <Section tone="base" size="sm">
        <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
          {RELATED.map((r) => (
            <Link
              key={r.href}
              href={r.href}
              className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
            >
              {r.label}
            </Link>
          ))}
        </div>
      </Section>
    </>
  );
}
