295	export async function listDir(server: SftpServer, path: string): Promise<SftpEntry[]> {
296	  if (SANDBOX) {
297	    const node = simResolve(server.id, path);
298	    if (!node) throw new Error("No such directory.");
299	    if (node.type !== "dir") throw new Error("Not a directory.");
300	    return Object.entries(node.children)
301	      .map(([name, child]) => ({
302	        name,
303	        type: child.type === "dir" ? "d" : "-",
304	        isDirectory: child.type === "dir",
305	        size: child.type === "file" ? Buffer.byteLength(child.content) : 0,
306	        modifiedMs: child.mtime,
307	        mode: child.mode,
308	      }))
309	      .sort((a, b) =>
310	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
311	      );
312	  }
313	
314	  return withSftp(server, async (client) => {
315	    const list = await client.list(path);
316	    return list
317	      .map((e) => ({
318	        name: e.name,
319	        type: e.type,
320	        isDirectory: e.type === "d",
321	        size: e.size,
322	        modifiedMs: e.modifyTime,
323	        // ssh2-sftp-client's list() returns rwx `rights` strings, not a numeric
324	        // mode — derive the octal permission bits from them.
325	        mode: rightsToMode(e.rights),
326	      }))
327	      .sort((a, b) =>
328	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
329	      );
330	  });
331	}
