447	/** Remove a file, or recursively remove a directory. */
448	export async function removePath(server: SftpServer, path: string): Promise<void> {
449	  if (SANDBOX) {
450	    const loc = simParent(server.id, path);
451	    if (!loc) throw new Error("Cannot remove the root.");
452	    if (!loc.parent.children[loc.name]) throw new Error("No such file or directory.");
453	    delete loc.parent.children[loc.name];
454	    return;
455	  }
456	
457	  await withSftp(server, async (client) => {
458	    const s = await client.stat(path);
459	    if (s.isDirectory) {
460	      await client.rmdir(path, true); // recursive
461	    } else {
462	      await client.delete(path);
463	    }
464	  });
465	}
