467	export async function chmodPath(server: SftpServer, path: string, mode: number): Promise<void> {
468	  if (SANDBOX) {
469	    const node = simResolve(server.id, path);
470	    if (!node) throw new Error("No such file or directory.");
471	    node.mode = mode & 0o777;
472	    return;
473	  }
474	
475	  await withSftp(server, async (client) => {
476	    await client.chmod(path, mode & 0o777);
477	  });
478	}
