43	export type CatalogMod = {
44	  id: string;
45	  name: string;
46	  slug: string;
47	  category: string;
48	  source: string;
49	  url: string | null;
50	  description: string | null;
51	  iconUrl: string | null;
52	  paid: boolean;
53	  featured: boolean;
54	  appliesToVariant: string | null;
55	  /** install state for THIS server: null = not installed. */
56	  status: string | null;
57	  error: string | null;
58	  /* ── verified upstream facts (scripts/verify-gamemods.ts) ──────────────
59	     Every one of these is read from the mod's own source. Where a source
60	     doesn't publish something it stays null/empty and the panel says so,
61	     rather than filling the gap with a plausible-looking number. */
62	  downloads: number | null;
