73	export type ModsView = {
74	  family: string;
75	  variant: string | null;
76	  /** catalog entries (compatible with the server's variant), grouped by category. */
77	  categories: { category: string; mods: CatalogMod[] }[];
78	  installedCount: number;
79	  busy: boolean;
80	  /** The version this server is pinned to, when its game has one. */
81	  gameVersion: string | null;
82	  /** What the installed set is asking of this server. */
