86	/**
87	 * Load the mod catalog for an owned game server, annotated with each mod's
88	 * install state on this server. Only mods for the server's game family and
89	 * compatible with its selected variant are returned.
90	 */
91	export async function getServerMods(
92	  serverId: string
93	): Promise<{ error?: string; view?: ModsView }> {
94	  const { server } = await ownedServer(serverId);
95	  const family = familyFor(server);
96	  if (!family) return { error: "This server doesn't support mods." };
97	
98	  const variant = server.gameVariant ?? null;
99	  /* The pinned game version lives in the per-family config blob under VERSION
100	     (a docker env var for the Minecraft images, not a server.properties key —
101	     see lib/game-config.ts). Families without one simply have no verdict. */
102	  const cfg = (server.gameConfig ?? null) as Record<string, unknown> | null;
103	  const rawVersion = cfg && typeof cfg.VERSION === "string" ? cfg.VERSION.trim() : "";
104	  // "LATEST"/"SNAPSHOT" name a moving target, not a version we can match against.
105	  const gameVersion = rawVersion && !/^(latest|snapshot)$/i.test(rawVersion) ? rawVersion : null;
106	
107	  const [catalog, installed, busy] = await Promise.all([
108	    db.gameMod.findMany({
109	      // A project that no longer resolves upstream would fail on install, so it
110	      // is not offered — see scripts/verify-gamemods.ts.
111	      where: { gameFamily: family, active: true, upstreamOk: true },
112	      orderBy: [{ featured: "desc" }, { popularity: "desc" }, { name: "asc" }],
113	      // Cap at CATALOG_LIST_CAP (lib/mods-catalog.ts) — scripts/import-modrinth-catalog.ts
114	      // can put thousands of real rows in one family; this panel renders every
115	      // row client-side (ModsPanel.tsx), so an unbounded findMany here is the
116	      // same "small catalogue" assumption that broke, just on the per-server
117	      // install UI instead of the marketing browse page. Best mods still show
118	      // first thanks to the ordering above.
119	      take: 400,
120	    }),
121	    db.serverMod.findMany({ where: { serverId } }),
122	    hasInflightJob(serverId),
123	  ]);
124	
125	  const stateByMod = new Map(installed.map((m) => [m.modId, m]));
126	
127	  // Hide mods that target a different loader/variant than the server runs.
128	  const compatible = catalog.filter(
129	    (m) => !m.appliesToVariant || !variant || m.appliesToVariant === variant
130	  );
131	
132	  const byCategory = new Map<string, CatalogMod[]>();
133	  for (const m of compatible) {
134	    const st = stateByMod.get(m.id);
135	    const row: CatalogMod = {
136	      id: m.id,
137	      name: m.name,
138	      slug: m.slug,
139	      category: m.category,
140	      source: m.source,
141	      url: m.url,
142	      description: m.description,
143	      iconUrl: m.iconUrl,
144	      paid: m.paid,
145	      featured: m.featured,
146	      appliesToVariant: m.appliesToVariant,
147	      status: st?.status ?? null,
148	      error: st?.error ?? null,
149	      downloads: m.downloads,
150	      fileBytes: m.fileBytes,
151	      dependencyCount: m.dependencyCount,
152	      impact: m.impact,
153	      impactNote: m.impactNote,
154	      verified: m.verifiedAt !== null,
155	      manualInstall: (() => {
156	        const sup = installSupport(family, m.source);
157	        return sup.ok ? null : sup.message;
158	      })(),
159	      compat: modCompat(
160	        { gameVersions: m.gameVersions, loaders: m.loaders, serverSide: m.serverSide },
161	        { gameVersion, variant },
162	      ),
163	    };
164	    const arr = byCategory.get(m.category) ?? [];
165	    arr.push(row);
166	    byCategory.set(m.category, arr);
167	  }
168	
169	  const categories = [...byCategory.entries()]
170	    .map(([category, mods]) => ({ category, mods }))
171	    .sort((a, b) => a.category.localeCompare(b.category));
172	
173	  const live = installed.filter((m) => m.status === "INSTALLED" || m.status === "INSTALLING");
174	  const byId = new Map(catalog.map((m) => [m.id, m]));
175	  const load = modLoad({
176	    // The game plan is what the customer bought and what sizes the VM; the base
177	    // plan only backs it. Falling back to 0 would claim a 0 GB server, so an
178	    // unknown size means no ratio rather than a wrong one.
179	    ramMB: server.gamePlan?.ramMB ?? 0,
180	    installed: live.map((s) => {
181	      const m = byId.get(s.modId);
182	      return { name: m?.name ?? "Unknown mod", fileBytes: m?.fileBytes ?? null, impact: m?.impact ?? "light" };
183	    }),
184	  });
185	
186	  return {
187	    view: { family, variant, categories, installedCount: live.length, busy, gameVersion, load },
188	  };
189	}
