191	/** Queue a mod for install on an owned server. */
192	export async function installMod(
193	  serverId: string,
194	  modId: string
195	): Promise<{ error?: string; ok?: boolean }> {
196	  const { user, server } = await ownedServer(serverId);
197	  const family = familyFor(server);
198	  if (!family) return { error: "This server doesn't support mods." };
199	
200	  const mod = await db.gameMod.findUnique({ where: { id: modId } });
201	  if (!mod || !mod.active) return { error: "That mod is unavailable." };
202	  if (mod.gameFamily !== family) return { error: "That mod isn't for this game." };
203	  if (mod.appliesToVariant && server.gameVariant && mod.appliesToVariant !== server.gameVariant) {
204	    return { error: `${mod.name} needs the "${mod.appliesToVariant}" server type.` };
205	  }
206	
207	  /* Refuse here rather than queue a GAME_MOD_SYNC that can only come back
208	     "auto-install isn't wired for this game". The panel already hides the
209	     button for these, so reaching this is a stale page or a direct call — but
210	     an unrunnable job would still take the server's one in-flight slot. */
211	  const support = installSupport(family, mod.source);
212	  if (!support.ok) return { error: support.message };
213	
214	  const existing = await db.serverMod.findUnique({
215	    where: { serverId_modId: { serverId, modId } },
216	  });
217	  if (existing && (existing.status === "INSTALLED" || existing.status === "INSTALLING")) {
218	    return { error: `${mod.name} is already installed.` };
219	  }
220	
221	  if (await hasInflightJob(serverId)) {
222	    return { error: "Another operation is already in progress on this server." };
223	  }
224	
225	  await db.serverMod.upsert({
226	    where: { serverId_modId: { serverId, modId } },
227	    create: { serverId, modId, status: "INSTALLING", error: null },
228	    update: { status: "INSTALLING", error: null },
229	  });
230	  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
231	  await db.auditLog.create({
232	    data: { userId: user.id, action: "gameserver.mod.install", detail: `${serverId} mod=${mod.slug}` },
233	  });
234	
235	  revalidatePath(`/dashboard/servers/${serverId}`);
236	  return { ok: true };
237	}
