239	/** Queue a mod for removal from an owned server. */
240	export async function uninstallMod(
241	  serverId: string,
242	  modId: string
243	): Promise<{ error?: string; ok?: boolean }> {
244	  const { user, server } = await ownedServer(serverId);
245	
246	  const existing = await db.serverMod.findUnique({
247	    where: { serverId_modId: { serverId, modId } },
248	    include: { mod: true },
249	  });
250	  if (!existing || existing.status === "REMOVED") {
251	    return { error: "That mod isn't installed." };
252	  }
253	
254	  if (await hasInflightJob(serverId)) {
255	    return { error: "Another operation is already in progress on this server." };
256	  }
257	
258	  await db.serverMod.update({
259	    where: { serverId_modId: { serverId, modId } },
260	    data: { status: "REMOVING", error: null },
261	  });
262	  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
263	  await db.auditLog.create({
