9	/**
10	 * GAME_MOD_SYNC handler — reconcile a game server's installed mods to the desired
11	 * state recorded in `ServerMod` rows:
12	 *   - status INSTALLING → fetch + install the mod, then INSTALLED (or FAILED)
13	 *   - status REMOVING   → remove the mod, then delete the row (or FAILED)
14	 *
15	 * Wire into worker/index.ts handlers:  GAME_MOD_SYNC: gameModSync,
16	 *
17	 * THREE PATHS, mirroring game-config's honesty guard so we never tell a customer a
18	 * mod is installed when nothing was written to their server:
19	 *  - SANDBOX: simulate (flip INSTALLING→INSTALLED, REMOVING→REMOVED). Dev only.
20	 *  - REAL (ENABLE_REAL_GAMEMODS=1, not sandbox): install/remove over SSH via the
21	 *    per-source adapter. Where an adapter isn't implemented yet, the mod is marked
22	 *    FAILED with a clear reason — never silently "INSTALLED".
23	 *  - Neither (production, flag off): mark the queued changes FAILED with a plain
24	 *    message. A change we did NOT apply is a failure and must say so.
25	 */
26	
27	const REAL_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMEMODS === "1";
28	
29	async function notify(userId: string, title: string, body?: string, href?: string) {
30	  try {
31	    await db.notification.create({ data: { userId, title, body, href } });
32	  } catch (e) {
33	    console.error("[game-mods] notify failed", e);
34	  }
35	}
