37	export async function gameModSync(job: Job): Promise<void> {
38	  const serverId = job.serverId;
39	  if (!serverId) throw new Error("game mod sync: job has no serverId");
40	
41	  const server = await db.server.findUnique({
42	    where: { id: serverId },
43	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
44	  });
45	  if (!server) throw new Error(`Server ${serverId} not found`);
46	
47	  const pending = await db.serverMod.findMany({
48	    where: { serverId, status: { in: ["INSTALLING", "REMOVING"] } },
49	    include: { mod: true },
50	  });
51	  if (pending.length === 0) return;
52	
53	  const installedNames: string[] = [];
54	  const removedNames: string[] = [];
55	  const failedNames: string[] = [];
56	
57	  for (const sm of pending) {
58	    const removing = sm.status === "REMOVING";
59	    try {
60	      if (SANDBOX) {
61	        // Dev simulation — no VM mutation.
62	        if (removing) {
63	          await db.serverMod.delete({ where: { id: sm.id } });
64	          removedNames.push(sm.mod.name);
65	        } else {
66	          await db.serverMod.update({ where: { id: sm.id }, data: { status: "INSTALLED", error: null } });
67	          installedNames.push(sm.mod.name);
68	        }
69	        continue;
70	      }
71	
72	      if (!REAL_ENABLED) {
73	        // Honest failure: nothing was applied. Do NOT report success.
74	        await db.serverMod.update({
75	          where: { id: sm.id },
76	          data: {
77	            status: "FAILED",
78	            error:
79	              "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified.",
80	          },
81	        });
82	        failedNames.push(sm.mod.name);
83	        continue;
84	      }
85	
86	      // REAL path — install/remove over SSH via the per-source adapter.
87	      const modRow: ModRowFull = {
88	        gameFamily: sm.mod.gameFamily,
89	        source: sm.mod.source,
90	        sourceId: sm.mod.sourceId,
91	        slug: sm.mod.slug,
92	        name: sm.mod.name,
93	        url: sm.mod.url,
94	        variant: server.gameVariant ?? null,
95	        appliesTo: sm.mod.appliesToVariant ?? null,
96	      };
97	      const result =
98	        sm.mod.source === "steam_workshop"
99	          ? await workshopSync(server, sm.mod.gameFamily, serverId)
100	          : removing
101	          ? await removeModReal(server, modRow)
102	          : await installModReal(server, modRow);
103	
104	      if (result.ok) {
105	        if (removing) {
106	          await db.serverMod.delete({ where: { id: sm.id } });
107	          removedNames.push(sm.mod.name);
108	        } else {
109	          await db.serverMod.update({
110	            where: { id: sm.id },
111	            data: { status: "INSTALLED", version: result.version ?? null, error: null },
112	          });
113	          installedNames.push(sm.mod.name);
114	        }
115	      } else {
116	        await db.serverMod.update({
117	          where: { id: sm.id },
118	          data: { status: removing ? "INSTALLED" : "FAILED", error: result.error ?? "install failed" },
119	        });
120	        failedNames.push(sm.mod.name);
121	      }
122	    } catch (e) {
123	      const msg = e instanceof Error ? e.message : String(e);
124	      console.error(`[game-mods] ${removing ? "remove" : "install"} failed for ${sm.mod.slug}:`, e);
125	      await db.serverMod.update({
126	        where: { id: sm.id },
127	        // A failed removal stays INSTALLED (it's still there); a failed install is FAILED.
128	        data: { status: removing ? "INSTALLED" : "FAILED", error: msg },
129	      });
130	      failedNames.push(sm.mod.name);
131	    }
132	  }
133	
134	  // One summary notification for the batch.
135	  const parts: string[] = [];
136	  if (installedNames.length) parts.push(`installed ${installedNames.join(", ")}`);
137	  if (removedNames.length) parts.push(`removed ${removedNames.join(", ")}`);
138	  if (failedNames.length) parts.push(`could not apply ${failedNames.join(", ")}`);
139	  const anyOk = installedNames.length > 0 || removedNames.length > 0;
140	  const allFailed = !anyOk && failedNames.length > 0;
141	
142	  await notify(
143	    server.userId,
144	    allFailed ? `Mod changes failed on ${server.hostname}` : `Mods updated on ${server.hostname}`,
145	    parts.length ? `${parts.join("; ")}.` : "No changes were made.",
146	    `/dashboard/servers/${server.id}?tab=mods`
147	  );
148	}
