150	// ===========================================================================
151	// Real install/remove — per-source adapters over SSH.
152	//
153	// Approach: the worker resolves a DIRECT download URL from the source's API, then
154	// SSHes into the game VM and has the VM itself `curl` the file into the game's
155	// plugin/mod directory (deterministic filename, so uninstall is a plain rm — no
156	// per-install state to track). Sources that need auth or per-repo handling
157	// (GitHub release zips, Nexus, CurseForge key, Codefling paid) soft-fail with a
158	// clear "install manually from <url>" note rather than faking success.
159	//
160	// Supported today: modrinth + spigotmc (Minecraft), umod (Rust), thunderstore
161	// (Valheim) — which fully covers those three games' catalogs. `steam_workshop`
162	// mods use a completely different mechanism — see the big Steam Workshop
163	// section near the end of this file — and never go through planTarget/
164	// resolveUrl/modDirShell below at all.
165	// ===========================================================================
166	
167	type ModResult = { ok: boolean; version?: string; error?: string };
168	type ModRow = {
169	  gameFamily: string;
170	  source: string;
171	  sourceId: string | null;
172	  slug: string;
173	  name: string;
174	  url: string | null;
175	};
176	type SshServer = {
177	  id: string;
178	  rootPassword: string | null;
179	  rootPasswordEnc?: string | null;
180	  sshPort: number | null;
181	  dedicatedIp?: { address: string } | null;
182	  node?: { publicIp: string } | null;
183	};
184	
185	const CONNECT_TIMEOUT_MS = 15_000;
186	const EXEC_TIMEOUT_MS = 200_000; // downloads can be large
187	
188	/** PascalCase a mod name for an Oxide/Carbon .cs filename (class-name convention). */
189	function pascal(name: string): string {
190	  const p = name.replace(/[^a-zA-Z0-9]+/g, " ").trim().split(/\s+/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
191	  return p || "Plugin";
192	}
193	
194	/** Deterministic on-disk target for a mod, or null if its source isn't installable. */
195	function planTarget(mod: ModRow): { kind: "jar" | "cs" | "zip"; file?: string; folder?: string } | null {
196	  switch (mod.source) {
197	    case "modrinth":
198	    case "spigotmc":
199	      return { kind: "jar", file: `nxeon-${mod.slug}.jar` };
200	    case "umod":
201	      return { kind: "cs", file: `${pascal(mod.name)}.cs` };
202	    case "thunderstore":
203	      return { kind: "zip", folder: `nxeon-${mod.slug}` };
204	    case "github":
205	      // Same "zip-of-a-folder" shape as thunderstore — a reasonable generic
206	      // default for a GitHub release asset, but untested against a real CS2
207	      // plugin's actual archive layout (addons/ layout vs. a bare .dll/.so vs.
208	      // a source tarball all differ per repo). Harmless today: no family in
209	      // INSTALLABLE_FAMILIES is github-sourced (see mod-install-support.ts),
210	      // so modDirShell always returns null first and this never actually runs
211	      // an install. Revisit this specific shape when a family is wired up.
212	      return { kind: "zip", folder: `nxeon-${mod.slug}` };
213	    default:
214	      return null; // nexus / curseforge / codefling / hangar — manual
215	  }
216	}
217	
218	/** Resolve a direct download URL from the source's API (worker-side). */
219	async function resolveUrl(mod: ModRowFull): Promise<string | null> {
220	  const id = mod.sourceId ?? "";
221	  try {
222	    switch (mod.source) {
223	      case "umod":
224	        return `https://umod.org/plugins/${id}.cs`;
225	      case "spigotmc":
226	        return `https://api.spiget.org/v2/resources/${id}/download`;
227	      case "modrinth": {
228	        const loader = modrinthLoader(mod);
229	        const q = loader ? `?loaders=["${loader}"]` : "";
230	        const res = await fetch(`https://api.modrinth.com/v2/project/${id}/version${q}`, {
231	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
232	        });
233	        if (!res.ok) return null;
234	        const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
235	        const v = versions[0];
236	        if (!v) return null;
237	        return (v.files.find((f) => f.primary) ?? v.files[0])?.url ?? null;
238	      }
239	      case "thunderstore": {
240	        const [author, ...rest] = id.split("-");
241	        if (!rest.length) return null;
242	        const res = await fetch(`https://thunderstore.io/api/experimental/package/${author}/${rest.join("-")}/`, {
243	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
244	        });
245	        if (!res.ok) return null;
246	        const pkg = (await res.json()) as { latest?: { download_url?: string } };
247	        return pkg.latest?.download_url ?? null;
248	      }
249	      case "github": {
250	        // id is "owner/repo" (scripts/import-github-catalog.ts's sourceId
251	        // convention, matching prisma/seed-gamemods.ts's pre-existing CS2
252	        // rows). Resolved fresh at install time, same as modrinth above —
253	        // nothing about the release is cached on the GameMod row, so a mod
254	        // author cutting a new release just works with no re-import needed.
255	        const headers: Record<string, string> = { "User-Agent": "Nxeon/1.0 (mod-manager)", Accept: "application/vnd.github+json" };
256	        if (process.env.GITHUB_TOKEN) headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
257	        const res = await fetch(`https://api.github.com/repos/${id}/releases/latest`, { headers });
258	        if (!res.ok) return null; // no releases yet, repo renamed/gone, or rate-limited
259	        const release = (await res.json()) as { assets?: Array<{ browser_download_url: string; name: string }> };
260	        const assets = release.assets ?? [];
261	        if (assets.length === 0) return null;
262	        // Prefer a real packaged archive over a loose source-only asset when both exist.
263	        const archive = assets.find((a) => /\.(zip|tar\.gz|tgz)$/i.test(a.name));
264	        return (archive ?? assets[0]).browser_download_url;
265	      }
266	      default:
267	        return null;
268	    }
269	  } catch (e) {
270	    console.error(`[game-mods] resolveUrl(${mod.source}/${id}) failed`, e);
271	    return null;
272	  }
273	}
274	
275	function modrinthLoader(mod: ModRowFull): string | null {
276	  // Prefer the mod's own loader target; fall back to the server's variant.
277	  const key = mod.appliesTo ?? mod.variant ?? "";
278	  const map: Record<string, string> = {
279	    paper: "paper", spigot: "spigot", purpur: "purpur", bukkit: "bukkit",
280	    fabric: "fabric", forge: "forge", neoforge: "neoforge", quilt: "quilt",
281	  };
282	  return map[key] ?? null;
283	}
284	
285	/** Shell snippet that echoes (creating if needed) the mod/plugin dir for family+variant. */
286	/* The shared set in lib/mod-install-support.ts is what the PANEL uses to decide
287	   whether to draw an Install button at all. If this switch ever grows a case
288	   that isn't in that set the button never appears, and if the set grows a
289	   family this switch doesn't handle the button appears and fails — which is the
290	   bug that module was written to end. Fail loudly here rather than let them
291	   drift apart silently. */
292	function modDirShell(family: string, variant: string | null): string | null {
293	  if (!INSTALLABLE_FAMILIES.has(family)) return null;
294	  switch (family) {
295	    case "minecraft": {
296	      const modded = variant && ["fabric", "forge", "neoforge", "quilt"].includes(variant);
297	      const sub = modded ? "mods" : "plugins";
298	      return `root=$(find /opt /srv /home /root -maxdepth 6 -name server.properties -printf '%h\\n' 2>/dev/null | head -1); [ -n "$root" ] && { mkdir -p "$root/${sub}"; echo "$root/${sub}"; }`;
299	    }
300	    case "rust":
301	      return `d=$(find /opt /srv /home -maxdepth 9 -type d \\( -name oxide -o -name carbon \\) 2>/dev/null | head -1); [ -n "$d" ] && { mkdir -p "$d/plugins"; echo "$d/plugins"; }`;
302	    // Was a case-sensitive `find -name BepInEx` — always a no-op even with
303	    // BepInEx installed, since lloesche/valheim-server's own real directory is
304	    // lowercase `bepinex` (confirmed against its README). Use the documented,
305	    // fixed path directly instead of searching for it: `/config` is the
306	    // catalog's own `-v /opt/valheim/config:/config` mount, and the image
307	    // itself watches `/config/bepinex/plugins` for user-added plugins and
308	    // copies them into the real BepInEx plugin dir on boot — this is the
309	    // customer-facing "drop mods here" folder by design, not an internal path.
310	    case "valheim":
311	      return `d=/opt/valheim/config/bepinex/plugins; [ -d /opt/valheim/config/bepinex ] && { mkdir -p "$d"; echo "$d"; }`;
312	    default:
313	      return null;
314	  }
315	}
316	
317	const shq = (s: string) => s.replace(/'/g, "'\\''");
318	
319	async function installModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
320	  const target = planTarget(mod);
321	  if (!target) {
322	    return { ok: false, error: `Auto-install isn't available for ${mod.source} mods yet — install manually${mod.url ? ` from ${mod.url}` : ""}.` };
323	  }
324	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
325	  if (!dirShell) {
326	    return { ok: false, error: `Auto-install isn't wired for this game yet.` };
327	  }
328	  if (!RESOLVABLE_SOURCES.has(mod.source)) {
329	    return { ok: false, error: `We can't fetch downloads from ${mod.source} — install this one by hand in Files.` };
330	  }
331	  const url = await resolveUrl(mod);
332	  if (!url) return { ok: false, error: "Could not resolve a download for this mod (it may have moved)." };
333	
334	  let cmd: string;
335	  if (target.kind === "zip") {
336	    cmd =
337	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
338	      `tmp=$(mktemp -d); if curl -fsSL --max-time 180 -o "$tmp/m.zip" '${shq(url)}'; then ` +
339	      `rm -rf "$dir/${target.folder}"; mkdir -p "$dir/${target.folder}"; ` +
340	      `unzip -oq "$tmp/m.zip" -d "$dir/${target.folder}" && echo OK || echo UNZIP; rm -rf "$tmp"; else echo FAIL; fi`;
341	  } else {
342	    cmd =
343	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
344	      `if curl -fsSL --max-time 180 -o "$dir/${target.file}" '${shq(url)}'; then echo OK; else echo FAIL; fi`;
345	  }
346	
347	  const out = await withSsh(server, (conn) => execRemote(conn, cmd));
348	  const s = out.stdout.trim();
349	  if (s.endsWith("OK")) return { ok: true };
350	  if (s.includes("NODIR")) return { ok: false, error: "Couldn't find the game's mod folder — is the server fully set up?" };
351	  if (s.includes("UNZIP")) return { ok: false, error: "Downloaded the mod but couldn't unpack it (unzip missing?)." };
352	  return { ok: false, error: "Download failed on the server." };
353	}
354	
355	async function removeModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
356	  const target = planTarget(mod);
357	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
358	  if (!target || !dirShell) return { ok: true }; // nothing we placed → nothing to remove
359	  const rm =
360	    target.kind === "zip"
361	      ? `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -rf "$dir/${target.folder}"; echo OK`
362	      : `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -f "$dir/${target.file}"; echo OK`;
363	  await withSsh(server, (conn) => execRemote(conn, rm));
364	  return { ok: true };
