371	function withSsh<T>(server: SshServer, fn: (conn: Client) => Promise<T>): Promise<T> {
372	  return new Promise((resolve, reject) => {
373	    const t = connectionTarget(server as any);
374	    if (!t) return reject(new Error("server is not reachable yet"));
375	    const password = serverRootPassword(server as any);
376	    if (!password) return reject(new Error("server has no root password set"));
377	    const conn = new Client();
378	    let settled = false;
379	    const finish = (err: Error | null, val?: T) => {
380	      if (settled) return;
381	      settled = true;
382	      try { conn.end(); } catch { /* best-effort */ }
383	      err ? reject(err) : resolve(val as T);
384	    };
385	    conn.on("ready", () => {
386	      fn(conn).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
387	    });
388	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
389	    conn.connect({ host: t.host, port: t.port, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
390	  });
391	}
