393	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
394	  return new Promise((resolve, reject) => {
395	    conn.exec(cmd, (err, stream: ClientChannel) => {
396	      if (err) return reject(err);
397	      let stdout = "";
398	      let stderr = "";
399	      const timer = setTimeout(() => { try { stream.close(); } catch { /* ignore */ } }, EXEC_TIMEOUT_MS);
400	      stream
401	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, stdout, stderr }); })
402	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
403	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
404	    });
405	  });
406	}
