549	async function readEnvMap(conn: Client, container: string): Promise<Map<string, string> | null> {
550	  const inspect = await execRemote(conn, `docker inspect ${container} --format '{{json .Config.Env}}'`);
551	  if (inspect.code !== 0) return null;
552	  try {
553	    const arr: string[] = JSON.parse(inspect.stdout.trim());
554	    const m = new Map<string, string>();
555	    for (const e of arr) {
556	      const i = e.indexOf("=");
557	      if (i >= 0) m.set(e.slice(0, i), e.slice(i + 1));
558	    }
559	    m.delete("PATH");
560	    return m;
561	  } catch {
562	    return null;
563	  }
564	}
