566	async function writeContainerEnvFile(conn: Client, sftp: SFTPWrapper, path: string, envMap: Map<string, string>): Promise<void> {
567	  const content = Array.from(envMap.entries()).map(([k, v]) => `${k}=${v.replace(/\r?\n/g, " ")}`).join("\n") + "\n";
568	  await sftpWrite(sftp, path, content);
569	  await execRemote(conn, `chmod 600 '${shq(path)}'`);
570	}
