572	async function resolveUnit(conn: Client, family: string): Promise<string | null> {
573	  const hints = controlSpec(family)?.serviceHints ?? [];
574	  if (!hints.length) return null;
575	  const probe = hints.map((h) => `systemctl cat '${shq(h)}.service' >/dev/null 2>&1 && { echo '${shq(h)}.service'; exit 0; };`).join(" ");
576	  const { stdout } = await execRemote(conn, probe);
577	  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.endsWith(".service"));
578	  return hit ?? null;
579	}
