735	/** Update `Key=Value` lines in a PZ-style ini, preserving everything else;
736	 *  append missing keys. Same shape as worker/game-config.ts's
737	 *  `updateKeyValue` for server.properties — kept as its own copy since that
738	 *  function isn't exported and this file deliberately doesn't import
739	 *  low-level helpers from game-config.ts (see the container-recreate
740	 *  section's comment above). */
741	function updateIniKeyValue(content: string, updates: Record<string, string>): string {
742	  const lines = content.split(/\r?\n/);
743	  const seen = new Set<string>();
744	  for (let i = 0; i < lines.length; i++) {
745	    const t = lines[i].trim();
746	    if (!t || t.startsWith("#")) continue;
747	    const eq = lines[i].indexOf("=");
748	    if (eq < 0) continue;
749	    const key = lines[i].slice(0, eq).trim();
750	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
751	      lines[i] = `${key}=${updates[key]}`;
752	      seen.add(key);
753	    }
754	  }
755	  for (const k of Object.keys(updates)) {
756	    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
757	  }
758	  return lines.join("\n");
759	}
