761	/**
762	 * Project Zomboid needs BOTH the numeric Workshop id (`WorkshopItems=`) AND
763	 * the mod's own internal string id from its `mod.info` file (`Mods=`) — two
764	 * different values, confirmed against PZwiki. The Workshop API never exposes
765	 * the second one; the only way to learn it is to look inside the mod's own
766	 * files. We do that with a single, throwaway `steamcmd workshop_download_item`
767	 * run INSIDE the customer's own container (Valve's own tool, on their own
768	 * VM — not a Nxeon download/mirror), read `mod.info`, then delete what we
769	 * fetched immediately — the dedicated server re-fetches its own real copy on
770	 * boot via `WorkshopItems=`, so nothing is kept or served from here. The
771	 * result is cached onto the `GameMod` row so this only ever runs once per
772	 * mod, for any server.
773	 */
774	async function resolvePzModStringId(conn: Client, sourceId: string): Promise<string | null> {
775	  const tmp = `/tmp/nxw-${sourceId.replace(/[^0-9]/g, "")}`;
776	  const cmd =
777	    `docker exec projectzomboid steamcmd +login anonymous +force_install_dir '${shq(tmp)}' +workshop_download_item ${PZ_APPID} ${shq(sourceId)} +quit >/dev/null 2>&1; ` +
778	    `docker exec projectzomboid sh -c "find '${shq(tmp)}' -iname mod.info 2>/dev/null | head -5 | xargs -r cat" 2>/dev/null; ` +
779	    `docker exec projectzomboid rm -rf '${shq(tmp)}' >/dev/null 2>&1`;
780	  const { stdout } = await execRemote(conn, cmd);
781	  const ids = [...stdout.matchAll(/^\s*id\s*=\s*(.+?)\s*$/gim)].map((m) => m[1].trim()).filter(Boolean);
782	  return ids.length ? ids.join(";") : null;
783	}
