787	async function applyProjectZomboidWorkshop(
788	  server: SshServer,
789	  mods: { sourceId: string; modStringId: string | null; gameModId: string }[]
790	): Promise<ModResult> {
791	  return withSftp(server, async (conn, sftp) => {
792	    const resolved: string[] = [];
793	    for (const m of mods) {
794	      if (m.modStringId) {
795	        resolved.push(m.modStringId);
796	        continue;
797	      }
798	      const found = await resolvePzModStringId(conn, m.sourceId);
799	      if (!found) {
800	        return {
801	          ok: false,
802	          error: `Could not read this mod's internal Mod ID from Steam Workshop item ${m.sourceId} — it may be private, removed, or not a real PZ mod.`,
803	        };
804	      }
805	      await db.gameMod.update({ where: { id: m.gameModId }, data: { modStringId: found }, select: { id: true } }).catch(() => {});
806	      resolved.push(found);
807	    }
