947	async function patchEmpyrionScenario(conn: Client, sftp: SFTPWrapper, root: string, scenarioName: string | null): Promise<ModResult> {
948	  const found = await execRemote(conn, `find '${shq(root)}' -maxdepth 8 -type f -iname 'dedicated.yaml' 2>/dev/null | head -1`);
949	  const path = found.stdout.trim();
950	  if (!path) return { ok: false, error: "Could not locate dedicated.yaml on this server — nothing was changed." };
951	  const existing = await sftpRead(sftp, path);
952	  if (existing == null) return { ok: false, error: "dedicated.yaml disappeared — nothing was changed." };
953	  if (!/^\s*CustomScenario\s*:/m.test(existing)) {
954	    return { ok: false, error: "Could not find a CustomScenario key in dedicated.yaml — set it manually to activate this scenario." };
955	  }
956	  const line = scenarioName ? `    CustomScenario: '${scenarioName}'` : `    CustomScenario: ''`;
957	  const updated = existing.replace(/^\s*CustomScenario\s*:.*$/m, line);
958	  await sftpWrite(sftp, path, updated);
959	  return { ok: true };
960	}
