969	  return withSftp(server, async (conn, sftp) => {
970	    const root = "/opt/empyrion";
971	    if (ids.length === 0) {
972	      return patchEmpyrionScenario(conn, sftp, root, null);
973	    }
974	    const id = ids[0];
975	    await execRemote(
976	      conn,
977	      `docker exec empyrion steamcmd +login anonymous +force_install_dir /home/user/Steam +workshop_download_item ${EMPYRION_APPID} ${shq(id)} +quit >/dev/null 2>&1`
978	    );
979	    const found = await execRemote(
980	      conn,
981	      `find '${shq(root)}/steamapps/workshop/content/${EMPYRION_APPID}/${shq(id)}' -maxdepth 1 -type d 2>/dev/null | head -1`
982	    );
983	    const contentDir = found.stdout.trim();
984	    if (!contentDir) {
985	      return { ok: false, error: `Could not fetch Steam Workshop scenario ${id} — it may be private, removed, or not an Empyrion scenario.` };
986	    }
987	    const scenariosDirRes = await execRemote(conn, `find '${shq(root)}' -maxdepth 8 -type d -path '*/Content/Scenarios' 2>/dev/null | head -1`);
988	    const scenariosDir = scenariosDirRes.stdout.trim();
989	    if (!scenariosDir) {
990	      return { ok: false, error: "Could not locate this server's Content/Scenarios directory — nothing was changed." };
991	    }
992	    const scenarioName = `nxw-${id}`;
993	    await execRemote(
994	      conn,
995	      `rm -rf '${shq(scenariosDir)}/${shq(scenarioName)}' && cp -r '${shq(contentDir)}' '${shq(scenariosDir)}/${shq(scenarioName)}'`
996	    );
997	    return patchEmpyrionScenario(conn, sftp, root, scenarioName);
998	  });
999	}
