50	  const user = await requireUser();
51	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
52	  if (!row) return { error: "You don't have a free server." };
53	
54	  const gameTypeKey = FREEMC_GAME_TYPES[row.activeGameType] ? row.activeGameType : "vanilla";
55	  const gameType = FREEMC_GAME_TYPES[gameTypeKey];
56	  if (gameType.kind !== "plugins") {
57	    return { error: "Your current game type doesn't run plugins, so there's nothing for extra mods to install into. Switch to a plugin-based game type first." };
58	  }
59	  const gameMode = FREEMC_GAME_MODES[row.activeGameMode] ?? FREEMC_GAME_MODES.survival;
60	
61	  const rl = checkRateLimit(`freemc:mods:${user.id}`, { max: 10, windowMs: 60_000 });
62	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
63	
64	  const submitted = formData.getAll("mods").map((v) => String(v));
65	  const invalid = submitted.filter((s) => !CATALOG_SLUGS.has(s));
66	  if (invalid.length > 0) {
67	    return { error: "One or more selected mods aren't recognized — please refresh and try again." };
68	  }
69	  const selected = [...new Set(submitted)];
70	
71	  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
72	  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
73	  const previousMods = row.extraMods;
74	
75	  // Extra mods are layered on top of whatever the game type's own env
76	  // already declares — merge onto MODRINTH_PROJECTS specifically, same as
77	  // before, rather than blindly overwriting the whole env object.
78	  function extraEnvFor(modSlugs: string[]): Record<string, string> {
79	    const baseSlugs = (gameType.env?.MODRINTH_PROJECTS ?? "").split(",").map((s) => s.trim()).filter(Boolean);
80	    const merged = [...new Set([...baseSlugs, ...modSlugs])];
81	    return { MODRINTH_PROJECTS: merged.join(",") };
82	  }
83	
84	  try {
85	    const host = await freemcHost();
86	    const outcome = await withServerSsh(host, async (conn) => {
87	      // Clear old plugin jars first — MODRINTH_PROJECTS only ADDS/updates
88	      // what it lists, it never prunes a jar no longer listed, so a mod the
89	      // owner just REMOVED would otherwise keep running.
90	      await exec(conn, `rm -rf ${shellQuote(`/opt/freemc/servers/${row.id}/plugins`)}`, 15_000).catch(() => {});
91	      const applied = await recreateGameTypeContainer(conn, {
92	        containerName: row.containerName,
93	        dataPath: `/opt/freemc/servers/${row.id}`,
94	        subdomain: row.subdomain,
95	        domain,
96	        ramMb,
97	        ownerId: user.id,
98	        gameType,
99	        gameTypeKey,
100	        gameMode,
101	        extraEnv: extraEnvFor(selected),
102	      });
103	      if (applied.ok) return { ok: true as const };
104	
105	      console.error("[freemc-mods] apply failed, rolling back:", applied.error);
106	      const rolledBack = await recreateGameTypeContainer(conn, {
107	        containerName: row.containerName,
108	        dataPath: `/opt/freemc/servers/${row.id}`,
109	        subdomain: row.subdomain,
110	        domain,
111	        ramMb,
112	        ownerId: user.id,
113	        gameType,
114	        gameTypeKey,
115	        gameMode,
116	        extraEnv: extraEnvFor(previousMods),
117	      });
118	      return rolledBack.ok
119	        ? { ok: false as const, error: "That mod selection didn't start cleanly, so we put your server back the way it was." }
120	        : { ok: false as const, error: "That mod selection didn't start, and restoring your previous setup also failed — please contact support." };
121	    });
122	    if (!outcome.ok) return { error: outcome.error };
123	  } catch (e) {
124	    console.error("[freemc-mods] apply failed:", e);
125	    return { error: "Couldn't apply your mod selection — please try again." };
126	  }
127	
128	  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { extraMods: selected } });
129	  revalidatePath("/dashboard/free-minecraft");
130	  return {};
131	}
